                post_hook={
                    "sql": "drop table if exists public.anveshan_AMAZON_FACT_ITEMS_INTERMEDIATE; CREATE TABLE public.anveshan_AMAZON_FACT_ITEMS_INTERMEDIATE AS SELECT \"fulfillment-channel\" AS shop_name, cast(\"amazon-order-id\" as varchar) order_id, cast(\"amazon-order-id\" AS varchar) order_name, NULL AS customer_id, NULL AS phone, NULL AS tags, NULL AS line_item_id, cast(Sku as varchar) sku, ASIN AS product_id, cast(Currency as varchar) Currency, CASE WHEN \"order-status\" IN (\'Shipped - Returned to Seller\', \'Shipped - Returning to Seller\', \'Shipped - Rejected by Buyer\', \'Shipped - Damaged\') THEN 1 ELSE 0 END AS is_refund, coalesce(pin.city,cast(UPPER(\"ship-city\") as varchar)) AS city, coalesce(pin.state,cast(UPPER(\"ship-state\") as varchar)) AS state, cast(\"ship-postal-code\" as varchar) AS pincode, upper(cast(\"product-name\" as varchar)) AS product_name, NULL AS category, cast(\"order-status\" as varchar)order_status, (SUBSTRING(\"purchase-date\", 1, 19)::TIMESTAMP + INTERVAL \'5 hours 30 minutes\') AS order_timestamp, COALESCE(TRY_CAST(\"item-price\" AS double precision), 0) AS line_item_sales, COALESCE(TRY_CAST(\"shipping-price\" AS double precision), 0) AS shipping_price, COALESCE(TRY_CAST(quantity AS double precision), 0) AS quantity, COALESCE(TRY_CAST(\"item-tax\" AS double precision), 0) AS tax, COALESCE(TRY_CAST(\"item-tax\" AS double precision), 0) / NULLIF(COALESCE(TRY_CAST(\"item-tax\" AS double precision), 0) + COALESCE(TRY_CAST(\"item-price\" AS double precision), 0), 0) AS tax_rate, COALESCE(TRY_CAST(\"item-promotion-discount\" AS double precision), 0) AS discount, CASE WHEN (COALESCE(TRY_CAST(\"item-tax\" AS double precision), 0) + COALESCE(TRY_CAST(\"item-price\" AS double precision), 0)) = 0 THEN 0 WHEN (1 - (COALESCE(TRY_CAST(\"item-tax\" AS double precision), 0) / (COALESCE(TRY_CAST(\"item-tax\" AS double precision), 0) + COALESCE(TRY_CAST(\"item-price\" AS double precision), 0)))) = 0 THEN 0 ELSE COALESCE(TRY_CAST(\"item-promotion-discount\" AS double precision), 0) / (1 - (COALESCE(TRY_CAST(\"item-tax\" AS double precision), 0) / (COALESCE(TRY_CAST(\"item-tax\" AS double precision), 0) + COALESCE(TRY_CAST(\"item-price\" AS double precision), 0)))) END AS discount_before_tax, NULL AS gross_sales_after_tax, COALESCE(TRY_CAST(\"item-price\" AS double precision), 0) - CASE WHEN (COALESCE(TRY_CAST(\"item-tax\" AS double precision), 0) + COALESCE(TRY_CAST(\"item-price\" AS double precision), 0)) = 0 THEN COALESCE(TRY_CAST(\"item-price\" AS double precision), 0) WHEN (1 - (COALESCE(TRY_CAST(\"item-tax\" AS double precision), 0) / NULLIF(COALESCE(TRY_CAST(\"item-tax\" AS double precision), 0) + COALESCE(TRY_CAST(\"item-price\" AS double precision), 0), 0))) = 0 THEN COALESCE(TRY_CAST(\"item-price\" AS double precision), 0) ELSE COALESCE(TRY_CAST(\"item-price\" AS double precision), 0) - (COALESCE(TRY_CAST(\"item-promotion-discount\" AS double precision), 0) / (1 - (COALESCE(TRY_CAST(\"item-tax\" AS double precision), 0) / NULLIF(COALESCE(TRY_CAST(\"item-tax\" AS double precision), 0) + COALESCE(TRY_CAST(\"item-price\" AS double precision), 0), 0)))) END AS gross_sales_before_tax, NULL AS net_sales_before_tax, COALESCE(TRY_CAST(\"item-price\" AS double precision), 0) AS total_sales, \'Amazon\' AS source, NULL AS landing_utm_medium, NULL AS landing_utm_source, NULL AS landing_utm_campaign, NULL AS referring_utm_medium, NULL AS referring_utm_source, NULL AS landing_utm_channel, NULL AS referring_utm_channel, NULL AS final_utm_channel, NULL AS new_customer_flag, NULL AS acquisition_channel, NULL AS acquisition_product, COALESCE(TRY_CAST(\"shipping-tax\" AS double precision), 0) AS shipping_tax, COALESCE(TRY_CAST(\"ship-promotion-discount\" AS double precision), 0) AS ship_promotion_discount, COALESCE(TRY_CAST(\"gift-wrap-price\" AS double precision), 0) AS gift_wrap_price, COALESCE(TRY_CAST(\"gift-wrap-tax\" AS double precision), 0) AS gift_wrap_tax, cast(null as varchar) AS Email, cast(null as varchar) AS Name, cast(null as varchar) as Recipient_Name, case when \"amazon-order-id\" like \'S%\' then \'Stock Transfer\' else \'Sale Order\' end as Order_Type FROM ( SELECT *, \"purchase-date\" AS Purchase_datetime_PDT FROM public.custom_amazon_seller_partner_anveshan_amazon_seller____get_flat_file_all_orders_data_by_last_update_general ) X left join (select * from (select trim(upper(\"Delivery City\")) as city, trim(upper(\"Delivery State\")) as state, trim(\"Delivery Pincode\") as pincode, row_number() over (partition by pincode order by 1) as rw from public.anveshan_location_mapping) where rw=1 ) pin on replace(pin.pincode,\' \',\'\') = cast(\"ship-postal-code\" as varchar) ; drop table if exists public.anveshan_AMAZON_FACT_ITEMS; CREATE TABLE public.anveshan_AMAZON_FACT_ITEMS AS SELECT fi.* ,upper(coalesce(p.product_name,p1.product_name)) AS product_name_final ,upper(COALESCE(p.CATEGORY,p1.category,fi.category::varchar)) AS product_category ,upper(coalesce(p.commonsku,p1.commonsku)) as commonsku ,coalesce(p.tax_rate,p1.tax_rate) as pm_tax_rate ,coalesce(p.cogs,p1.cogs) as cogs FROM public.anveshan_AMAZON_FACT_ITEMS_INTERMEDIATE fi LEFT JOIN ( SELECT * FROM ( SELECT master_sku as commonsku, amazon_sku as marketplace_sku, parent_category as category, tax_rate, product_name, parent_mrp, cogs, ROW_NUMBER() OVER (PARTITION BY amazon_sku ORDER BY LENGTH(COALESCE(amazon_sku, \'\')) DESC) rw FROM public.anveshan_sku_master ) WHERE rw = 1 ) p ON trim(LOWER(REPLACE(REPLACE(fi.sku::varchar, \' \', \'\'),\'\"\',\'\'))) = trim(LOWER(p.marketplace_sku)) LEFT JOIN ( SELECT * FROM ( SELECT master_sku as commonsku, parent_category as category, tax_rate, product_name, parent_mrp, cogs, ROW_NUMBER() OVER (PARTITION BY master_sku ORDER BY LENGTH(COALESCE(master_sku, \'\')) DESC) rw FROM public.anveshan_sku_master ) WHERE rw = 1 ) p1 ON trim(LOWER(REPLACE(REPLACE(fi.sku::varchar, \' \', \'\'),\'\"\',\'\'))) = trim(LOWER(p1.commonsku)) ;",
